def run_length_encode(s: str) -> str:
    if not s:
        return ""

    encoded = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            encoded.append(str(count))
            encoded.append(s[i - 1])
            count = 1

    # Append the last run
    encoded.append(str(count))
    encoded.append(s[-1])

    return ''.join(encoded)

