    compressed = []
    start = nums[0]

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1] + 1:
            continue
        else:
            if start != nums[i - 1]:
                compressed.append(f"{start}")
            compressed.append(f"{nums[i - 1]}-{nums[i]}" if nums[i] > start + 1 else str(nums[i]))
